let LIGHT_SOURCES = 5;
const ENABLE_ORBIT_CONTROL = false;
const ENABLE_DIRECTIONAL_LIGHT = true;

if (LIGHT_SOURCES > 5) {
    LIGHT_SOURCES = 5;
}
const MAX_RGB_VALUE = 255/LIGHT_SOURCES;
const D_MAX_RGB_VALUE = MAX_RGB_VALUE*2;
const MIN_SPEED = 8;
const MAX_SPEED = MIN_SPEED*2;

let canvas;
const canvasSize = 640;
const h_canvasSize = canvasSize/2;
const wallThickness = 36;
const h_wallThickness = wallThickness/2;
const d_wallThickness = wallThickness*2;
let cameraZ = 0;
let directionalLightColor;
let shouldLoop = true;
const lightSources = [];

class LightSource {
    constructor(r, x, y, z, speed) {
        this.r = r;
        this.x = x * (round(random(-1, 1)) > 0 ? 1 : -1);
        this.y = y * (round(random(-1, 1)) > 0 ? 1 : -1);
        this.z = z * (round(random(-1, 1)) > 0 ? 1 : -1);
        this.speed = speed;
        this.dirX = speed * (round(random(-1, 1)) > 0 ? 1 : -1);
        this.dirY = speed * (round(random(-1, 1)) > 0 ? 1 : -1);
        this.dirZ = speed * (round(random(-1, 1)) > 0 ? 1 : -1);
        this.color = color(
            floor(random()*D_MAX_RGB_VALUE),
            floor(random()*D_MAX_RGB_VALUE),
            floor(random()*D_MAX_RGB_VALUE)
        );
    }

    draw() {
        push();
        pointLight(this.color, 0, 0, cameraZ);
        translate(this.x, this.y, this.z);
        sphere(this.r, 24, 24);
        pop();

        pointLight(this.color, this.x, this.y, this.z);

        this.x += this.dirX;
        this.y += this.dirY;
        this.z += this.dirZ;

        const maxX = h_canvasSize-this.r;
        const minX = -h_canvasSize+this.r;
        if (this.dirX > 0 && this.x > maxX) {
            this.dirX = -this.speed;
        } else if (this.dirX < 0 && this.x < minX) {
            this.dirX = this.speed;
        }

        const maxY = maxX;
        const minY = minX;
        if (this.dirY > 0 && this.y > maxY) {
            this.dirY = -this.speed;
        } else if (this.dirY < 0 && this.y < minY) {
            this.dirY = this.speed;
        }

        const maxZ = maxX;
        const minZ = minX;
        if (this.dirZ > 0 && this.z > maxZ) {
            this.dirZ = -this.speed;
        } else if (this.dirZ < 0 && this.z < minZ) {
            this.dirZ = this.speed;
        }
    }
}

function setup() {
    canvas = createCanvas(canvasSize, canvasSize, WEBGL);
    noStroke();
    // if (! ENABLE_ORBIT_CONTROL) {
    //     noCursor();
    // }

    cameraZ = canvasSize+h_canvasSize-d_wallThickness*2;
    if (ENABLE_ORBIT_CONTROL) {
        cameraZ *= 1.382;
    }
    camera(0, 0, cameraZ);

    const maxR = canvasSize*0.382*0.382*0.382;
    const minR = maxR*0.382;
    for (let i = 0; i < LIGHT_SOURCES; i++) {
        const lightSource = new LightSource(
            random(minR, maxR),
            random(-h_canvasSize, h_canvasSize),
            random(-h_canvasSize, h_canvasSize),
            random(-h_canvasSize, h_canvasSize),
            random(MIN_SPEED, MAX_SPEED)
        );
        lightSources.push(lightSource);
    }

    if (ENABLE_DIRECTIONAL_LIGHT) {
        directionalLightColor = color(
            floor(random()*MAX_RGB_VALUE),
            floor(random()*MAX_RGB_VALUE),
            floor(random()*MAX_RGB_VALUE)
        );
    }
}

function draw() {
    background(100);
    if (ENABLE_ORBIT_CONTROL) {
        orbitControl();
    }
    if (ENABLE_DIRECTIONAL_LIGHT) {
        directionalLight(directionalLightColor, -1, -1, -1);
    }
    for (let i = 0; i < lightSources.length; i++) {
        lightSources[i].draw();
    }
    drawRoom();
}

function drawRoom() {
    // left wall
    push();
    translate(-h_canvasSize-h_wallThickness, 0, 0);
    box(wallThickness, canvasSize+d_wallThickness, canvasSize);
    pop();
    // top wall
    push();
    translate(0, -h_canvasSize-h_wallThickness, 0);
    box(canvasSize+d_wallThickness, wallThickness, canvasSize);
    pop();
    // right wall
    push();
    translate(h_canvasSize+h_wallThickness, 0, 0);
    box(wallThickness, canvasSize+d_wallThickness, canvasSize);
    pop();
    // bottom wall
    push();
    translate(0, h_canvasSize+h_wallThickness, 0);
    box(canvasSize+d_wallThickness, wallThickness, canvasSize);
    pop()
    // end wall
    push();
    translate(0, 0, -h_canvasSize);
    plane(canvasSize, canvasSize);
    pop();
}

function keyPressed() {
    switch (keyCode) {
        case 32: // SPACE
            shouldLoop = ! shouldLoop;
            if (shouldLoop) {
                loop();
            } else {
                // noLoop() removed for animation
            }
            break;
        case 83: // S
            save(canvas, 'export.png');
            break;
        default: break;
    }
}
